import { useContext, useState, useEffect } from "react";
import { AuthContext } from "../../context/authContext";
import { Link } from "react-router-dom";
import axios from "axios";
import Friends from "../../assets/1.png";
import Groups from "../../assets/2.png";
import Gallery from "../../assets/8.png";
import Videos from "../../assets/9.png";
import Messages from "../../assets/10.png";
import Addfrnds from "../../assets/add_frnds.png";
import "./leftBar.scss";

const LeftBar = () => {
  const { currentUser } = useContext(AuthContext);
  const [friends, setFriends] = useState([]);
  const [showFriends, setShowFriends] = useState(false);
  const [loading, setLoading] = useState(false);
  const [error, setError] = useState(null);

  useEffect(() => {
    if (!currentUser?.id) return;

    const fetchFriends = async () => {
      setLoading(true);
      try {
        console.log('Fetching user friends for ID:', currentUser.id);
        const res = await axios.get(`http://localhost:5000/api/users/${currentUser.id}`, {
          headers: { Authorization: `Bearer ${localStorage.getItem('token')}` },
        });
        console.log('Fetched friends:', res.data.friends);
        setFriends(res.data.friends || []);
        setError(null);
      } catch (err) {
        console.error('Fetch friends error:', err.response?.data || err.message);
        setError(err.response?.data?.message || 'Failed to load friends');
      } finally {
        setLoading(false);
      }
    };

    fetchFriends();
  }, [currentUser?.id]);

  const handleFriendsClick = () => {
    setShowFriends(!showFriends);
  };

  const getProfilePictureUrl = (profilePicture) => {
    return profilePicture
      ? `http://localhost:5000${profilePicture}?t=${new Date().getTime()}`
      : '/default-avatar.png';
  };

  return (
    <div className="leftBar">
      <div className="container">
        <div className="menu">
          <div className="user">
            {currentUser ? (
              <Link to={`/profile/${currentUser.id}`} style={{ textDecoration: 'none' }}>
                <span>View Your Profile</span>
                <span>{currentUser.name}</span>
              </Link>
            ) : (
              <span>Loading...</span>
            )}
          </div>
          <Link
            to="/friends"
            className="item"
            style={{ textDecoration: 'none' }}
            onClick={handleFriendsClick}
          >
            <img src={Friends} alt="Friends icon" />
            <span>Friends</span>
          </Link>
          {showFriends && (
            <div className="friends-list">
              <h3>Your Friends</h3>
              {loading ? (
                <p>Loading friends...</p>
              ) : error ? (
                <p className="error">{error}</p>
              ) : friends.length > 0 ? (
                friends.map((friend) => (
                  <Link
                    to={`/profile/${friend._id}`}
                    className="friend"
                    key={friend._id}
                    style={{ textDecoration: 'none' }}
                  >
                    <img
                      src={getProfilePictureUrl(friend.profilePicture)}
                      alt={`${friend.name}'s profile`}
                      onError={(e) => console.error('Friend image load error:', e)}
                    />
                    <span>{friend.name}</span>
                  </Link>
                ))
              ) : (
                <p>No friends found.</p>
              )}
            </div>
          )}
          <Link to="/groups" className="item" style={{ textDecoration: 'none' }}>
            <img src={Groups} alt="Groups icon" />
            <span>Groups</span>
          </Link>
        </div>
        <hr />
        <div className="menu">
          <span>Your shortcuts</span>
          <Link to="/add-friends" className="item" style={{ textDecoration: 'none' }}>
            <img src={Addfrnds} alt="Add Friends icon" />
            <span>Add Friends</span>
          </Link>
          <Link to="/photos" className="item" style={{ textDecoration: 'none' }}>
            <img src={Gallery} alt="Photos icon" />
            <span>Photos</span>
          </Link>
          <Link to="/videos" className="item" style={{ textDecoration: 'none' }}>
            <img src={Videos} alt="Videos icon" />
            <span>Videos</span>
          </Link>
          <Link to="/messages" className="item" style={{ textDecoration: 'none' }}>
            <img src={Messages} alt="Messages icon" />
            <span>Messages</span>
          </Link>
        </div>
        <hr />
      </div>
    </div>
  );
};

export default LeftBar;
